from typing import List

def process_intents(commands: List[str]) -> List[str]:
    merchants = {}   # merchant_id -> balance
    intents = {}     # intent_id -> [merchant_id, amount, state]
    for cmd in commands:
        p = cmd.split()
        op = p[0]
        if op == "INIT":
            if p[1] not in merchants:
                merchants[p[1]] = int(p[2])
        elif op == "CREATE":
            pid, mid, amt = p[1], p[2], int(p[3])
            if pid in intents or mid not in merchants or amt < 0:
                continue
            intents[pid] = [mid, amt, "REQUIRES_ACTION"]
        elif op == "UPDATE":
            pid, new_amt = p[1], int(p[2])
            it = intents.get(pid)
            if it and it[2] == "REQUIRES_ACTION" and new_amt >= 0:
                it[1] = new_amt
        elif op == "ATTEMPT":
            it = intents.get(p[1])
            if it and it[2] == "REQUIRES_ACTION":
                it[2] = "PROCESSING"
        elif op == "SUCCEED":
            it = intents.get(p[1])
            if it and it[2] == "PROCESSING":
                it[2] = "COMPLETED"
                merchants[it[0]] += it[1]
    return [f"{m} {merchants[m]}" for m in sorted(merchants)]
